from collections import OrderedDict
import time

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._cache = OrderedDict()
        self.stats = {
            'hits': 0,
            'misses': 0,
            'evictions': 0,
            'expirations': 0,
        }

    def put(self, key, value):
        if self.capacity == 0:
            return
        current_time = self.clock()
        if key in self._cache:
            self._cache[key] = (value, current_time + self.ttl)
            self._cache.move_to_end(key, last=True)
        else:
            expired_keys = [k for k in self._cache if self._cache[k][1] <= current_time]
            for k in expired_keys:
                del self._cache[k]
            if len(self._cache) >= self.capacity:
                evicted_key, _ = self._cache.popitem(last=False)
                self.stats['evictions'] += 1
            self._cache[key] = (value, current_time + self.ttl)
            self._cache.move_to_end(key, last=True)

    def get(self, key, default=None):
        current_time = self.clock()
        if key not in self._cache:
            self.stats['misses'] += 1
            return default
        expiry = self._cache[key][1]
        if expiry <= current_time:
            del self._cache[key]
            self.stats['misses'] += 1
            self.stats['expirations'] += 1
            return default
        else:
            self._cache.move_to_end(key, last=True)
            self.stats['hits'] += 1
            return self._cache[key][0]

    def __len__(self):
        current_time = self.clock()
        count = 0
        for key in self._cache:
            if self._cache[key][1] > current_time:
                count += 1
        return count

    def stats(self):
        return self.stats.copy()
