import re

def parse_duration(s: str) -> int:
    s_clean = s.replace(' ', '')
    if not s_clean:
        raise ValueError("Empty string")
    parts = re.findall(r'(\d+)([hmsHMS])', s_clean)
    parsed_str = ''.join([num + unit for num, unit in parts])
    if parsed_str != s_clean:
        raise ValueError("Invalid format")
    units = []
    for num_str, unit in parts:
        unit_lower = unit.lower()
        if unit_lower not in {'h', 'm', 's'}:
            raise ValueError("Unknown unit")
        if unit_lower in units:
            raise ValueError("Repeated unit")
        units.append(unit_lower)
    for i in range(1, len(units)):
        if units[i] < units[i-1]:
            raise ValueError("Units out of order")
    total = 0
    for num_str, unit in parts:
        num = int(num_str)
        unit_lower = unit.lower()
        if unit_lower == 'h':
            total += num * 3600
        elif unit_lower == 'm':
            total += num * 60
        elif unit_lower == 's':
            total += num
    return total
