import unicodedata
import re

def slugify(title: str, max_len: int = 50) -> str:
    normalized = unicodedata.normalize('NFKD', title)
    ascii_chars = [c for c in normalized if ord(c) <= 127]
    ascii_str = ''.join(ascii_chars)
    lower_str = ascii_str.lower()
    step3 = re.sub(r'[^a-z0-9]+', '-', lower_str).strip('-')
    if len(step3) <= max_len:
        return step3
    words = step3.split('-')
    prefix = []
    current_length = 0
    for word in words:
        if not prefix:
            possible_length = len(word)
        else:
            possible_length = current_length + len(word) + 1
        if possible_length > max_len:
            break
        else:
            prefix.append(word)
            current_length = possible_length
    if not prefix:
        if words:
            slug = words[0][:max_len]
        else:
            slug = ''
    else:
        slug = '-'.join(prefix)
    return slug
