class TokenBucket:
    def __init__(self, capacity: float, refill_per_sec: float, clock):
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self.current_tokens = capacity
        self.last_time = clock()

    def _refill(self):
        now = self.clock()
        elapsed = now - self.last_time
        self.current_tokens += self.refill_per_sec * elapsed
        if self.current_tokens > self.capacity:
            self.current_tokens = self.capacity
        self.last_time = now

    def allow(self, cost: float = 1) -> bool:
        self._refill()
        if self.current_tokens >= cost:
            self.current_tokens -= cost
            return True
        else:
            return False

    @property
    def tokens(self) -> float:
        self._refill()
        return self.current_tokens
